INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(5201, 'Deuteronomy 28:30', 'Deuteronomy', 28, 30, '&nbsp;تاسو به د يوې پېغلې سره کوژدن وکړئ، خو بل څوک به د هغې سره څملى. تاسو به يو کور جوړ کړئ، خو هيڅکله به په هغې کښې ونۀ وسېږئ. تاسو به د انګورو باغ وکَرئ، خو د هغې انګور به هيڅکله ونۀ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5202, 'Deuteronomy 28:31', 'Deuteronomy', 28, 31, '&nbsp;ستاسو څاروے به د ستاسو د سترګو په وړاندې حلال شى، خو تاسو به يې غوښه ونۀ خورئ. ستاسو په وړاندې به ستاسو خرونه بوتلے شى خو تاسو له به واپس در نۀ کړے شى، ستاسو ګډې به ستاسو دشمنانو له ورکړے شى خو ستاسو د مدد دپاره به هيڅ څوک نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5203, 'Deuteronomy 28:32', 'Deuteronomy', 28, 32, '&nbsp;ستاسو زامن او لوڼه به نورو قومونو له غلامان ورکړے شى تاسو به همېشه هغوئ ته سترګې په لار يئ خو هيڅ به هم نۀ شئ کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5204, 'Deuteronomy 28:33', 'Deuteronomy', 28, 33, '&nbsp;يو پردے قوم به هغه ټول فصلونه يوسى چې د هغې په کَرلو کښې تاسو ډېره سخته خوارى کړې وى، خو په هغه وخت کښې به تاسو ته د سخت کړاؤ او بد سلوک نه بغېر هيڅ نۀ ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5205, 'Deuteronomy 28:34', 'Deuteronomy', 28, 34, '&nbsp;او دا تکليفونه چې تاسو وينئ نو تاسو به ليونى شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5206, 'Deuteronomy 28:35', 'Deuteronomy', 28, 35, '&nbsp;مالِک خُدائ به ستاسو پښې په لا علاجه او دردناکو زخمونو پټې کړى، د سر نه تر پښو پورې به په تاسو باندې دانې راوخېژى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5207, 'Deuteronomy 28:36', 'Deuteronomy', 28, 36, '&nbsp;مالِک خُدائ به تاسو او ستاسو بادشاه يو پردى مُلک ته بوځى، هلته به مخکښې هيڅکله نۀ تاسو او نۀ ستاسو پلار نيکۀ اوسېدلى وى، هلته به تاسو د داسې معبودانو خِدمت کوئ چې د لرګى او کاڼى نه جوړ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5208, 'Deuteronomy 28:37', 'Deuteronomy', 28, 37, '&nbsp;په کومو مُلکونو کښې چې مالِک خُدائ تاسو خوارۀ وارۀ کړى، نو تاسو به د خلقو دپاره يروونکى شئ، هغوئ به په تاسو پورې ټوقې او مسخرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5209, 'Deuteronomy 28:38', 'Deuteronomy', 28, 38, '&nbsp;تاسو به ښۀ ډېر تخم وکَرئ، خو لږ فصل به ترې ورېبئ، ځکه چې د قحطۍ مُلخان به ستاسو فصلونه وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5210, 'Deuteronomy 28:39', 'Deuteronomy', 28, 39, '&nbsp;تاسو به د انګورو باغونه وکَرئ او د هغې ساتنه به وکړئ، خو تاسو به نۀ د هغې نه انګور راغونډ کړئ او نۀ به يې مے وڅښئ، ځکه چې چينجى به انګور وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5211, 'Deuteronomy 28:40', 'Deuteronomy', 28, 40, '&nbsp;د زيتُونو ونې به ستاسو په مُلک کښې شوى وى، خو هيڅ د زيتُونو تېل به تاسو ته مِلاو نۀ شى، ځکه چې زيتون به کچه راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5212, 'Deuteronomy 28:41', 'Deuteronomy', 28, 41, '&nbsp;ستاسو به زامن او لوڼه وى، خو تاسو به يې د ځان سره نۀ شئ ساتلے، ځکه چې هغوئ به قېديان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5213, 'Deuteronomy 28:42', 'Deuteronomy', 28, 42, '&nbsp;ستاسو ټولې ونې او فصلونه به د قحطۍ مُلخان خراب‌تُراب کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5214, 'Deuteronomy 28:43', 'Deuteronomy', 28, 43, '&nbsp;ستاسو په مُلک کښې چې کوم د پردى مُلک خلق اوسيږى هغوئ به ورځ په ورځ په تاسو زورَور کيږى او تاسو به ورځ په ورځ کمزورى کېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5215, 'Deuteronomy 28:44', 'Deuteronomy', 28, 44, '&nbsp;هغوئ سره به پېسې وى چې تاسو له يې قرض درکړى، خو تاسو سره به هيڅ نۀ وى چې تاسو يې هغوئ له قرض ورکړئ. په آخر کښې به هغوئ ستاسو بادشاهان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5216, 'Deuteronomy 28:45', 'Deuteronomy', 28, 45, '&nbsp;دا ټول افتونه به په تاسو راشى او دا افتونه به ستاسو تر تباهۍ پورې تاسو سره وى، ځکه چې تاسو د مالِک خُدائ د خپل خُدائ پاک فرمانبردارى ونۀ کړه او په هغه ټول قانون باندې تاسو عمل ونۀ کړو چې هغۀ درکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5217, 'Deuteronomy 28:46', 'Deuteronomy', 28, 46, '&nbsp;دا افتونه به د يوې نښې او خبردارى په شان ستاسو او ستاسو د اولاد په مينځ کښې د همېشه دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5218, 'Deuteronomy 28:47', 'Deuteronomy', 28, 47, '&nbsp;مالِک خُدائ تاسو له په هر څۀ کښې برکت درکړے دے، خو تاسو په خوشحالۍ او د زړۀ د اخلاصه د هغۀ خِدمت ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5219, 'Deuteronomy 28:48', 'Deuteronomy', 28, 48, '&nbsp;نو بيا به تاسو د هغه دشمنانو خِدمت کوئ چې مالِک خُدائ يې ستاسو خِلاف درلېږى. تاسو به اوږى، تږى، بربنډ او د هر څۀ حاجتمند يئ. مالِک خُدائ به تاسو سخت وکَړوى تر دې پورې چې تباه شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5220, 'Deuteronomy 28:49', 'Deuteronomy', 28, 49, '&nbsp;مالِک خُدائ به ستاسو خِلاف د لرې ځائ نه يو قوم راولى، هغه قوم چې تاسو به يې په ژبه نۀ پوهېږئ. هغوئ به د باز په شان په تاسو باندې راغوټه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5221, 'Deuteronomy 28:50', 'Deuteronomy', 28, 50, '&nbsp;هغوئ به يو ظالم او بې‌رحمه قوم وى چې نۀ به د مشرانو عزت کوى او نۀ به په کشرانو رحم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5222, 'Deuteronomy 28:51', 'Deuteronomy', 28, 51, '&nbsp;هغوئ به ستاسو څاروى او فصلونه وخورى او تاسو به د لوږې نه مړۀ شئ. هغوئ به ستاسو غله، مے، د زيتُونو تېل، څاروى او ګډې هيڅ هم نۀ پرېږدى، او تاسو به مړۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5223, 'Deuteronomy 28:52', 'Deuteronomy', 28, 52, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک چې کوم مُلک تاسو له درکوى هغوئ به د هغې په هر ښار باندې حمله وکړى او په کومو اوچتو او پَخو دېوالونو باندې چې تاسو اعتبار کوئ هغه به راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5224, 'Deuteronomy 28:53', 'Deuteronomy', 28, 53, '&nbsp;کله چې ستاسو دشمنان ستاسو ښارونه محاصره کوى، نو تاسو به دومره اوږى شئ چې مالِک خُدائ ستاسو خُدائ پاک تاسو له کوم بچى درکړى وى نو هغه به هم وخورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5225, 'Deuteronomy 28:58', 'Deuteronomy', 28, 58, '&nbsp;کۀ تاسو په وفادارۍ د خُدائ پاک ټولې لارښودنې ونۀ منئ کومې چې په دې کِتاب کښې ليکلے شوى دى او کۀ تاسو د مالِک خُدائ ستاسو خُدائ پاک عجيبه او هيبتناک نوم نه ونۀ يرېږئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5226, 'Deuteronomy 28:59', 'Deuteronomy', 28, 59, '&nbsp;نو هغه به په تاسو او ستاسو په اولاد باندې داسې لاعلاجه بيمارۍ او دردناکې وباګانې راولېږى چې هغه به هيڅکله نۀ بنديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5227, 'Deuteronomy 28:60', 'Deuteronomy', 28, 60, '&nbsp;هغه به يو ځل بيا په تاسو باندې هغه ټولې يروونکې بيمارۍ راولى چې په تاسو باندې په مِصر کښې تېرې شوې وى او تاسو به هيڅکله روغ نۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5228, 'Deuteronomy 28:61', 'Deuteronomy', 28, 61, '&nbsp;هغه به هغه هر قِسم بيمارۍ او وباګانې هم راولېږى چې هغه د خُدائ پاک د قانون په دې کِتاب کښې نۀ دى بيان شوى او تاسو به تباه شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5229, 'Deuteronomy 28:62', 'Deuteronomy', 28, 62, '&nbsp;اګر چې تاسو به د آسمان د ستورو په شان بې‌شمېره شئ، خو صِرف ستاسو يو څو کسان به ژوندى پاتې شى، ځکه چې تاسو د مالِک خُدائ د خپل خُدائ پاک فرمانبردارى ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5230, 'Deuteronomy 28:63', 'Deuteronomy', 28, 63, '&nbsp;لکه څنګه چې مالِک خُدائ په خوشحالۍ سره تاسو کامياب کړئ او ستاسو شمېر يې زيات کړو، نو هم دغه شان هغه به خوشحالۍ سره تاسو تباه کړى او تباهى به درباندې راولى. تاسو به د هغه مُلک د بېخ نه وويستلے شئ کوم چې تاسو قبضه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5231, 'Deuteronomy 28:64', 'Deuteronomy', 28, 64, '&nbsp;مالِک خُدائ به تاسو په ټولو قومونو کښې د دُنيا د يو سر نه تر بل سره پورې خوارۀ وارۀ کړى او هلته به تاسو د هغه معبودانو خِدمت کوئ چې د لرګى او کاڼو نه جوړ وى، د هغه بُتانو چې د دې نه مخکښې نۀ تاسو او نۀ ستاسو پلار نيکۀ د هغې عبادت کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5232, 'Deuteronomy 28:65', 'Deuteronomy', 28, 65, '&nbsp;په هغه قومونو کښې به هيچرته تاسو ته امن نۀ ملاويږى، تاسو ته به يو ځائ کښې هم آرام نۀ ملاويږى، مالِک خُدائ به ستاسو پرېشانى، نا‌اُميدى او غم د حد نه زيات کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5233, 'Deuteronomy 28:66', 'Deuteronomy', 28, 66, '&nbsp;ستاسو ژوند به همېشه په خطره کښې وى. شپه او ورځ به تاسو يرېږئ او تاسو به هر وخت د مرګ په يره کښې ژوند تېروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5234, 'Deuteronomy 28:67', 'Deuteronomy', 28, 67, '&nbsp;تاسو چې هر څۀ هم ګورئ نو زړونه به مو د يرې نه درزيږى. هر سحر به تاسو د ماښام ارمان کوئ، او هر ماښام به تاسو د سحر ارمان کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5235, 'Deuteronomy 28:68', 'Deuteronomy', 28, 68, '&nbsp;مالِک خُدائ به تاسو په سمندرى جهاز کښې واپس مِصر ته ولېږى، اګر چې هغۀ فرمائيلى وُو چې تاسو به هيڅکله هلته بيا نۀ ځئ. هلته به تاسو دا کوشش وکړئ چې خپل ځانونه په دشمنانو باندې غلامان خرڅ کړئ، خو هيڅ څوک به تاسو نۀ اخلى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5236, 'Deuteronomy 29:1', 'Deuteronomy', 29, 1, '&nbsp;دا د هغه لوظ خبرې دى چې مالِک خُدائ موسىٰ ته وفرمائيل چې د موآب په مُلک کښې د بنى اِسرائيلو سره دا لوظ وکړى، دا ټولې خبرې د هغه لوظ نه علاوه وې چې مالِک خُدائ د سينا په غرۀ باندې د هغوئ سره کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5237, 'Deuteronomy 29:2', 'Deuteronomy', 29, 2, '&nbsp;موسىٰ ټول بنى اِسرائيليان راوغوښتل او ورته يې وفرمائيل، ”تاسو په خپلو سترګو وليدل چې مالِک خُدائ په فِرعون، د هغۀ په ټولو درباريانو او د هغۀ په ټول مُلک باندې څۀ وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5238, 'Deuteronomy 29:3', 'Deuteronomy', 29, 3, '&nbsp;تاسو سختې وباګانې، معجزې او لوئې نښې وليدې چې مالِک خُدائ وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5239, 'Deuteronomy 29:4', 'Deuteronomy', 29, 4, '&nbsp;خو تر نن ورځې پورې مالِک خُدائ تاسو له د پوهېدو دپاره عقل، د ليدلو سترګې او د اورېدو غوږونه نۀ دى درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5240, 'Deuteronomy 29:5', 'Deuteronomy', 29, 5, '&nbsp;څلوېښت کاله په بيابان کښې مالِک خُدائ ستاسو لارښودنه وکړه او ستاسو جامې او څپلۍ هيڅکله نۀ دى زَړې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5241, 'Deuteronomy 29:6', 'Deuteronomy', 29, 6, '&nbsp;کۀ څۀ هم چې تاسو سره د خوراک دپاره نه روټۍ او نه د څښلو دپاره درسره مے او شراب وُو، خو مالِک خُدائ ستاسو د ضرورت پوره کولو دپاره تاسو له خوراک درکړو چې تاسو په دې پوهه شئ چې هغه ستاسو خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5242, 'Deuteronomy 29:7', 'Deuteronomy', 29, 7, '&nbsp;او کله چې مونږ دې ځائ ته راغلو، نو د حسبون بادشاه سيحون او د بسن بادشاه عوج زمونږ خِلاف جنګ له راووتل. خو مونږ هغوئ له شکست ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5243, 'Deuteronomy 29:8', 'Deuteronomy', 29, 8, '&nbsp;د هغوئ مُلک مو ونيولو او دا مونږ د روبين او جاد په قبيلو او د منسى په نيمه قبيله باندې تقسيم کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5244, 'Deuteronomy 29:9', 'Deuteronomy', 29, 9, '&nbsp;په وفادارۍ سره د دې لوظ ټول شرطونه ومنئ، نو داسې به تاسو په هر کار کښې کامياب يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5245, 'Deuteronomy 29:10', 'Deuteronomy', 29, 10, '&nbsp;نن ستاسو ټول سړى، ستاسو مشران او آفسران د مالِک خُدائ ستاسو خُدائ پاک په حضور کښې ولاړ دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5246, 'Deuteronomy 29:11', 'Deuteronomy', 29, 11, '&nbsp;هم داسې ستاسو ښځې ستاسو بچى، او هغه مسافر چې هغوئ ستاسو سره اوسيږى او لرګى درله پرې کوى او تاسو له اوبۀ راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5247, 'Deuteronomy 29:12', 'Deuteronomy', 29, 12, '&nbsp;نن تاسو د هغه لوظ دپاره راغلى يئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو سره کوى چې هغه د قسم په شان پوخ دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5248, 'Deuteronomy 29:13', 'Deuteronomy', 29, 13, '&nbsp;نو چې تاسو د مالِک خُدائ خلق يئ او هغه ستاسو خُدائ پاک وى، لکه څنګه چې هغۀ تاسو، ستاسو پلار نيکۀ اِبراهيم، اِسحاق او يعقوب سره وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5249, 'Deuteronomy 29:14', 'Deuteronomy', 29, 14, '&nbsp;صِرف تاسو هغه خلق نۀ يئ چې د چا سره مالِک خُدائ دا لوظ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5250, 'Deuteronomy 29:15', 'Deuteronomy', 29, 15, '&nbsp;هغه دا لوظ زمونږ ټولو سره کوى کوم چې نن دلته د مالِک خُدائ زمونږ خُدائ پاک په مخکښې ولاړ يُو او زمونږ د اولاد سره هم چې هغوئ لا پېدا شوى نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5251, 'Deuteronomy 29:16', 'Deuteronomy', 29, 16, '&nbsp;ستاسو به ياد وى چې په مِصر کښې ژوند څنګه وو او د نورو قومونو په علاقه کښې د تېرېدو سفر څنګه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5252, 'Deuteronomy 29:17', 'Deuteronomy', 29, 17, '&nbsp;تاسو د هغوئ مردار بُتان وليدل چې د لرګى، کاڼى، سپينو زرو او سرو زرو نه جوړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5253, 'Deuteronomy 29:18', 'Deuteronomy', 29, 18, '&nbsp;پام کوئ چې يو سړے، ښځه، خاندان او يوه قبيله هم د مالِک خُدائ ستاسو خُدائ پاک نه وانۀ وړى کوم چې نن دلته حاضر يئ چې تاسو د نورو قومونو د معبودانو عبادت وکړئ. دا به د يوې داسې جرړې په شان وى چې يو ترخه او زهرژنه مېوه ترې نه جوړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5254, 'Deuteronomy 29:19', 'Deuteronomy', 29, 19, '&nbsp;پام کوئ چې دلته نن هيڅ څوک هم داسې نۀ وى چې هغه د دې لوظ خبرې اورى او خپل ځان له دا تسلى ورکوى چې کۀ هغه د خپل ضدى زړۀ په خوښى پسې هم ځى نو هغه به محفوظ وى، دا به ښۀ او بد دواړه تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5255, 'Deuteronomy 29:20', 'Deuteronomy', 29, 20, '&nbsp;مالِک خُدائ به داسې سړے نۀ معاف کوى. د مالِک خُدائ سخت قهر او د هغۀ سخت غېرت به د هغۀ خِلاف شى او په دې کِتاب کښې ليکلے شوى ټول لعنتونه به په هغۀ رانازل شى تر دې پورې چې مالِک خُدائ هغه پوره تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5256, 'Deuteronomy 29:21', 'Deuteronomy', 29, 21, '&nbsp;مالِک خُدائ به هغه د بنى اِسرائيلو ټولو قبيلو په مخکښې د عبرت يوه نمونه جوړه کړى او يوه تباهى به ورباندې راولى هم هغه شان څنګه چې هغه ټول لعنتونه په هغه لوظ کښې شوى دى کوم چې مالِک خُدائ د لارښودنې په دې کِتاب کښې ليکلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5257, 'Deuteronomy 29:22', 'Deuteronomy', 29, 22, '&nbsp;په راتلونکى نسلونو کښې ستاسو اولاد او د لرې مُلکونو مسافر به هغه تباهى او تکليفونه وګورى چې مالِک خُدائ ستاسو په مُلک باندې راوستلى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5258, 'Deuteronomy 29:23', 'Deuteronomy', 29, 23, '&nbsp;پټى به شنډ شى، په زېړو ګوګړو او مالګه به پټ شى، هيڅ څۀ به په دې کښې نۀ شى کَرلے، هغه واښۀ قدرې به هم په کښې نۀ کيږى. ستاسو مُلک به د سدوم او عموره، ادمه او ضبوئيم په شان وى، چې مالِک خُدائ تباه کړى وُو په کوم وخت چې هغه سخت په قهر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5259, 'Deuteronomy 29:24', 'Deuteronomy', 29, 24, '&nbsp;بيا به ټوله دُنيا وائى چې، ”د هغوئ په مُلک يې دا ولې وکړل؟ څۀ وجه وه چې هغه دومره سخت په قهر وو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5260, 'Deuteronomy 29:25', 'Deuteronomy', 29, 25, '&nbsp;نو د هغې جواب به دا وى چې، ”د مِصر نه راويستلو په وخت چې خُدائ پاک د هغوئ پلار نيکۀ کوم لوظ کړے وو، نو د مالِک خُدائ خلقو هغه مات کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5261, 'Deuteronomy 29:26', 'Deuteronomy', 29, 26, '&nbsp;هغوئ د هغه معبودانو عبادت وکړو چې مخکښې يې هيڅکله نۀ وو کړے، د هغه معبودانو چې مالِک خُدائ د هغوئ د عبادت نه منع کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5262, 'Deuteronomy 29:27', 'Deuteronomy', 29, 27, '&nbsp;نو مالِک خُدائ خپلو خلقو ته په قهر شو او د هغوئ په مُلک يې هغه ټول لعنتونه راوستل چې په دې کِتاب کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5263, 'Deuteronomy 29:28', 'Deuteronomy', 29, 28, '&nbsp;مالِک خُدائ سخت په قهر شو او د خپل لوئ قهر په وجه يې د هغوئ د مُلک نه راوويستل او يو پردى مُلک ته يې وشړل او هغوئ تر نن ورځ پورې هلته دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5264, 'Deuteronomy 29:29', 'Deuteronomy', 29, 29, '&nbsp;داسې څۀ خبرې شته دے چې مالِک خُدائ زمونږ خُدائ پاک هغه په راز کښې ساتلى دى او څۀ يې زمونږ او زمونږ د اولاد دپاره څرګندې کړې دى د دې دپاره چې مونږ د هغۀ د قانون ټولې خبرې همېشه ومنو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5265, 'Deuteronomy 30:1', 'Deuteronomy', 30, 1, '&nbsp;ما تاسو له د برکت او لعنت په مينځ کښې خوښه درکړې ده. کله چې په تاسو باندې دا ټول کارونه شوى وى او تاسو د هغه قومونو په مينځ کښې اوسېږئ چرته چې مالِک خُدائ ستاسو خُدائ پاک خوارۀ وارۀ کړى يئ، نو تاسو به هغه خوښه راياده کړئ چې ما درکړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5266, 'Deuteronomy 30:2', 'Deuteronomy', 30, 2, '&nbsp;کۀ تاسو او ستاسو اولاد مالِک خُدائ ته راواپس شئ او د زړۀ د اخلاصه د هغۀ حُکمونه ومنئ کوم چې نن زۀ درکوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5267, 'Deuteronomy 30:3', 'Deuteronomy', 30, 3, '&nbsp;نو مالِک خُدائ ستاسو خُدائ پاک به په تاسو رحم وکړى. هغه به تاسو واپس د هغه قومونو نه راولى چرته چې هغۀ تاسو خوارۀ وارۀ کړى يئ او هغه به بيا تاسو نېک بخته کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5268, 'Deuteronomy 30:4', 'Deuteronomy', 30, 4, '&nbsp;کۀ د دُنيا آخرى سر ته هم لېږلے شوى يئ، نو مالِک خُدائ ستاسو خُدائ پاک به تاسو راغونډ کړى او واپس به مو راولى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5269, 'Deuteronomy 30:5', 'Deuteronomy', 30, 5, '&nbsp;هغه به تاسو هغه مُلک ته راولى چرته چې ستاسو پلار نيکۀ اوسېدل او دا به قبضه کړئ. او هغه به تاسو نور هم کامياب کړى او تاسو به په شمېر کښې د خپل پلار نيکۀ نه هم زيات کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5270, 'Deuteronomy 30:6', 'Deuteronomy', 30, 6, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک به ستاسو او ستاسو د اولاد زړونه بدل کړى، نو تاسو به د زړۀ د اخلاصه د هغۀ سره مينه کوئ او په هغه مُلک کښې به تاسو ژوند تېروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5271, 'Deuteronomy 30:7', 'Deuteronomy', 30, 7, '&nbsp;مالِک خُدائ به دا ټول لعنتونه ستاسو په دشمنانو واچوى، چې هغوئ ستاسو نه کرکه کوله او تاسو يې کړَولى يئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5272, 'Deuteronomy 30:8', 'Deuteronomy', 30, 8, '&nbsp;او تاسو به بيا د هغۀ فرمانبردارى کوئ او د هغۀ ټول حُکمونه به منئ کوم چې نن زۀ درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5273, 'Deuteronomy 30:9', 'Deuteronomy', 30, 9, '&nbsp;مالِک خُدائ به تاسو په هر کار کښې کاميابوى، ستاسو به ډېر اولاد او ډېر څاروى وى او ستاسو پټى به ډېر فصلونه پېدا کوى. هغه به ستاسو په کاميابولو باندې دومره خوشحاله وى لکه څنګه چې هغه ستاسو د پلار نيکۀ په کاميابولو خوشحاله وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5274, 'Deuteronomy 30:10', 'Deuteronomy', 30, 10, '&nbsp;خو تاسو به د هغۀ تابعدارى کوئ او د هغۀ په ټولو حُکمونو به عمل کوئ کوم چې د هغۀ د شريعت په دې کِتاب کښې ليکلى دى. تاسو به د زړۀ د اخلاصه هغۀ ته راوګرځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5275, 'Deuteronomy 30:11', 'Deuteronomy', 30, 11, '&nbsp;نن چې زۀ کوم حُکم درکوم هغه ډېر ګران نۀ دے او نۀ ستا د وس نه بهر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5276, 'Deuteronomy 30:12', 'Deuteronomy', 30, 12, '&nbsp;دا خو څۀ په آسمان کښې نۀ دے. چې تاسو به داسې ووايئ چې څوک پاس آسمان ته ختلے شى، او مونږ له به يې راکوز کړى، چې مونږ يې واورو او عمل پرې وکړُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5277, 'Deuteronomy 30:13', 'Deuteronomy', 30, 13, '&nbsp;نۀ دا د سمندر نه پورې غاړه دے. تاسو به دا نۀ وايئ چې څوک به د سمندر نه پورې وځى چې مونږ له يې راوړى، چې مونږ يې واورو او عمل پرې وکړُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5278, 'Deuteronomy 30:14', 'Deuteronomy', 30, 14, '&nbsp;بلکې هغه پېغام تاسو سره نزدې دے، دا ستاسو په شونډو او ستاسو په زړۀ کښې دے، چې عمل پرې وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5279, 'Deuteronomy 30:15', 'Deuteronomy', 30, 15, '&nbsp;ګورئ زۀ نن ستاسو په وړاندې يو طرف ته ژوند او خوشحالى ږدم او بل طرف ته مرګ او تباهى ږدم چې تاسو به څۀ خوښوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5280, 'Deuteronomy 30:16', 'Deuteronomy', 30, 16, '&nbsp;کۀ تاسو د مالِک خُدائ خپل خُدائ پاک حُکمونه ومنئ، کوم چې نن زۀ درکوم، کۀ تاسو د هغۀ سره مينه کوئ، د هغۀ په لارو تلل کوئ او د هغۀ په ټول قانون عمل کوئ، نو تاسو به کامياب شئ او د ډېرو خلقو قوم به شئ. مالِک خُدائ ستاسو خُدائ پاک به تاسو له په هغه مُلک کښې برکت درکړى چې تاسو يې قبضه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5281, 'Deuteronomy 30:17', 'Deuteronomy', 30, 17, '&nbsp;خو کۀ تاسو د هغۀ نه واوړئ او د هغۀ فرمانبردارى نۀ کوئ او د نورو معبودانو د عبادت دپاره بې‌لارې کول کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5282, 'Deuteronomy 30:18', 'Deuteronomy', 30, 18, '&nbsp;نو تاسو به تباه شئ، زۀ نن تاسو له خبردارے درکوم. تاسو به په هغه مُلک کښې ډېره موده تېره نۀ کړئ کوم چې د اُردن نه پورې دے چې تاسو يې قبضه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5283, 'Deuteronomy 30:19', 'Deuteronomy', 30, 19, '&nbsp;زۀ نن تاسو له د ژوند او مرګ، د خُدائ پاک د برکت او د خُدائ پاک د لعنت په مينځ کښې فېصله په تاسو پرېږدم او زۀ آسمان او زمکې ته وايم چې د هغې ګواه وى چې تاسو يې خوښوئ. ژوند خوښ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5284, 'Deuteronomy 30:20', 'Deuteronomy', 30, 20, '&nbsp;د مالِک خُدائ خپل خُدائ پاک سره مينه کوئ، د هغۀ فرمانبردارى کوئ او د هغۀ وفادار شئ نو بيا به تاسو او ستاسو اولاد په هغه مُلک کښې ډېره موده تېره کړئ چې هغۀ ستاسو پلار نيکۀ، اِبراهيم، اِسحاق او يعقوب سره د ورکولو وعده کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5285, 'Deuteronomy 31:1', 'Deuteronomy', 31, 1, '&nbsp;نو موسىٰ د بنى اِسرائيلو سره خپلې خبرې جارى وساتلې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5286, 'Deuteronomy 31:2', 'Deuteronomy', 31, 2, '&nbsp;او وې فرمائيل چې، ”زۀ اوس د يو سل او شلو کالو يم او زۀ نور ستاسو د مشرۍ جوګه نۀ يم. او مالِک خُدائ ما ته دا هم فرمائيلى دى چې زۀ به د اُردن نه پورې نۀ ووځم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5287, 'Deuteronomy 31:3', 'Deuteronomy', 31, 3, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک به په خپله ستاسو نه مخکښې پورې وځى او هغه قومونه به تباه کړى چې هلته اوسيږى، نو تاسو به د هغوئ مُلک قبضه کړئ، او يشوَع به ستاسو مشر وى، لکه څنګه چې مالِک خُدائ فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5288, 'Deuteronomy 31:4', 'Deuteronomy', 31, 4, '&nbsp;مالِک خُدائ به هغه خلق هغه شان تباه کړى، لکه څنګه چې هغۀ د اموريانو بادشاهان سيحون او عوج تباه کړى وُو او د هغوئ مُلک يې تباه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5289, 'Deuteronomy 31:5', 'Deuteronomy', 31, 5, '&nbsp;مالِک خُدائ به تاسو له په هغوئ باندې فتح درکړى او تاسو به د هغوئ سره خامخا هم هغه شان کار کوئ لکه څنګه چې ما درته وئيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5290, 'Deuteronomy 31:6', 'Deuteronomy', 31, 6, '&nbsp;تکړه او زړَور اوسئ. د هغوئ نه مۀ يرېږئ. مالِک خُدائ ستاسو خُدائ پاک به په خپله تاسو سره وى. هغه به کله هم تاسو سره بې‌وفائى ونۀ کړى او نۀ به مو يواځې پرېږدى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5291, 'Deuteronomy 31:7', 'Deuteronomy', 31, 7, '&nbsp;بيا موسىٰ يشوَع راوغوښتلو او د ټولو بنى اِسرائيلو په مخکښې يې هغۀ ته وفرمائيل، ”تکړه او زړَور اوسه، تۀ هغه کس يې چې د دې خلقو رهنمائى به کوې چې هغه مُلک قبضه کړى چې مالِک خُدائ يې د هغوئ پلار نيکۀ سره وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5292, 'Deuteronomy 31:8', 'Deuteronomy', 31, 8, '&nbsp;مالِک خُدائ به په خپله ستاسو لارښودنه کوى او هغه به تاسو سره وى. هغه به کله هم تاسو سره بې‌وفائى ونۀ کړى او نۀ به مو يواځې پرېږدى، نو يرېږئ مه او حوصله مۀ بائيلئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5293, 'Deuteronomy 31:9', 'Deuteronomy', 31, 9, '&nbsp;نو موسىٰ د خُدائ پاک قانون وليکلو او دا يې هغه ليوى اِمامانو، کومو چې د مالِک خُدائ د لوظ صندوق وړلو او د بنى اِسرائيلو مشرانو له يې ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5294, 'Deuteronomy 31:10', 'Deuteronomy', 31, 10, '&nbsp;هغۀ هغوئ له حُکم ورکړو، ”د هر اوؤم کال په آخر کښې يعنې کله چې د قرضونو د معاف کولو کال راځى، نو د جونګړو په اختر کښې دا په اوچت آواز سره وايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5295, 'Deuteronomy 31:11', 'Deuteronomy', 31, 11, '&nbsp;دا ټولو بنى اِسرائيلو ته وايئ کله چې هغوئ د مالِک خُدائ ستاسو خُدائ پاک د عبادت دپاره، د عبادت هغه يو ځائ ته راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5296, 'Deuteronomy 31:12', 'Deuteronomy', 31, 12, '&nbsp;سړى، ښځې، ماشومان او مسافر چې ستاسو په ښارونو کښې اوسيږى، دا ټول راوغواړه، چې هغوئ دا واورى او د مالِک خُدائ ستاسو خُدائ پاک نه يرېدل زده کړى او چې د هغۀ د قانون په ټولو خبرو پوره عمل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5297, 'Deuteronomy 31:13', 'Deuteronomy', 31, 13, '&nbsp;نو ستاسو هغه اولاد چا چې هيڅکله د مالِک خُدائ ستاسو خُدائ پاک قانون نۀ دے اورېدلے نو هغوئ به يې واورى. نو هغوئ به د هغۀ فرمانبردارى زده کړى چې هغوئ په هغه مُلک کښې تر کومې پورې اوسيږى چې هغه د اُردن نه پورې دے او تاسو يې قبضه کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5298, 'Deuteronomy 31:14', 'Deuteronomy', 31, 14, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”ستا د مرګ ورځې رانزدې دى. يشوَع راوغواړه او مقدسې خېمې ته يې راوله، چې هلته هغۀ ته نصيحت وکړم.“ نو موسىٰ او يشوَع خېمې ته لاړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5299, 'Deuteronomy 31:15', 'Deuteronomy', 31, 15, '&nbsp;او مالِک خُدائ هلته د وريځې د ستن په شکل کښې څرګند شو چې د خېمې د دروازې په خولۀ کښې ولاړه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5300, 'Deuteronomy 31:16', 'Deuteronomy', 31, 16, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”ستا د مرګ نېټه پوره کېدونکې ده او د خپل پلار نيکۀ سره به يو ځائ شې او ستا د مرګ نه پس به خلق زما نه نافرمانه شى او هغه لوظ به مات کړى چې ما د هغوئ سره کړے دے. هغوئ به ما پرېږدى او د هغه مُلک د غېرو معبودانو عبادت به وکړى چې کوم ته هغوئ ورننوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');